// Normaliza el mensaje de Telegram y decide de quien es.
//
// - Si el chat es el de la tienda (TELEGRAM_ADMIN_ID), es una consulta de negocio.
// - Si no, es un cliente: se busca su telefono (en los datos estaticos del flujo,
//   donde queda apuntado el chat) o se le pide.
const config = {};
for (const item of $('Parsear configuracion').all()) {
  const clave = String(item.json?.clave ?? '').trim();
  const valor = String(item.json?.valor ?? '').trim();
  if (clave) config[clave] = valor;
}

// Telegram manda el update en el cuerpo del webhook.
const telegram = $('Telegram Trigger').first().json ?? {};
const cuerpoBruto = telegram.body ?? telegram;
const mensaje = cuerpoBruto.message ?? cuerpoBruto;
const chat_id = String(mensaje.chat?.id ?? telegram.chat?.id ?? '').trim();
const texto = String(mensaje.text ?? telegram.text ?? '').trim();
const nombre = String(mensaje.from?.first_name ?? telegram.from?.first_name ?? '').trim();

const admin = String(config.TELEGRAM_ADMIN_ID ?? '').trim();
const es_tienda = admin.length > 0 && chat_id === admin;

// Telefono apuntado a este chat (el bot lo guarda la primera vez).
const staticData = $getWorkflowStaticData('global');
staticData.telegram = staticData.telegram ?? {};
const apuntado = String(staticData.telegram[chat_id] ?? '').trim();

// Si el cliente escribe un telefono de 9 digitos, se apunta.
const digitos = (texto.match(/\d/g) || []).join('');
const telefonoEnElMensaje = digitos.length === 9 ? digitos : '';
const telefono = apuntado || telefonoEnElMensaje;

if (!apuntado && telefonoEnElMensaje) {
  staticData.telegram[chat_id] = telefonoEnElMensaje;
}

return [{
  json: {
    chat_id,
    nombre,
    texto,
    es_tienda,
    telefono,
    telefone_nuevo: !apuntado && telefonoEnElMensaje ? telefonoEnElMensaje : '',
    admin_configurado: admin.length > 0,
  },
}];

// Respuesta para la tienda: las cifras del periodo, tal cual las devuelve la API.
const cifras = $('Cifras de la tienda').first().json ?? {};
const entrada = $('Normalizar el mensaje').first().json ?? {};

const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';

const lineas = [
  'Periodo: ' + cifras.periodo + ' (' + (cifras.desde ?? '') + ' a ' + (cifras.hasta ?? '') + ')',
  'Ventas directas: ' + euros(cifras.ventas_directas),
  'Abonos: ' + euros(cifras.abonos),
  'Recaudado: ' + euros(cifras.recaudacion),
  'Pendiente de cobro: ' + euros(cifras.pendiente_cobro),
  'Apartados activos: ' + (cifras.apartados_activos ?? 0),
];

if ((cifras.vencen_este_mes ?? []).length) {
  lineas.push('');
  lineas.push('Apartados que vencen este mes:');
  for (const a of cifras.vencen_este_mes) {
    lineas.push('- ' + a.cliente + ' | ' + a.producto + ' | pendiente ' + euros(a.pendiente) + ' | limite ' + a.fecha_limite);
  }
}

return [{
  json: {
    ...entrada,
    respuesta: lineas.join('\n'),
  },
}];

// Un cliente solo puede ver SUS apartados: el chat queda apuntado a un telefono
// y solo se consultan los apartados de ese telefono.
const entrada = $input.first().json ?? {};
const digitos = (s) => String(s ?? '').replace(/[^0-9]/g, '');

const telefono = digitos(entrada.telefono);
const tiene = telefono.length === 9;

return [{
  json: {
    ...entrada,
    telefono,
    tiene_telefono: tiene,
    pide_telefono: !tiene,
  },
}];

// Monta la respuesta del cliente con los datos de la API y la lista de cifras
// que tiene que aparecer en la respuesta (para poder comprobarla despues).
const saldo = $('Saldo del cliente').first().json ?? {};
const entrada = $('Datos del cliente').first().json ?? {};

const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';
const fecha = (f) => {
  const t = String(f ?? '').split('-');
  return t.length === 3 ? t[2] + '/' + t[1] + '/' + t[0] : String(f ?? '');
};

const lineas = [];
const cifras = [];

if (saldo.encontrado) {
  for (const a of (saldo.apartados ?? [])) {
    const producto = [a.producto, a.talla].filter(Boolean).join(' · ');
    lineas.push('- ' + producto + ': te queda ' + euros(a.pendiente) + ' (abonado ' + euros(a.abonado) + ' de ' + euros(a.precio) + '). Fecha limite: ' + fecha(a.fecha_limite) + '.');
    cifras.push(euros(a.pendiente).replace(' EUR', ''));
  }
  cifras.push(euros(saldo.total_pendiente).replace(' EUR', ''));
}

const respuesta_segura = saldo.encontrado
  ? [
      'Hola ' + (entrada.nombre ? entrada.nombre : '') + ',',
      '',
      'Esto es lo que tienes pendiente en la tienda:',
      '',
      lineas.join('\n'),
      '',
      'Total pendiente: ' + euros(saldo.total_pendiente) + '.',
      'Puedes pagar en la tienda cuando quieras. Si necesitas otro dato, dímelo.',
    ].join('\n')
  : 'No he encontrado ningún apartado con ese teléfono. ¿Me lo confirmas? '
    + 'Si lo prefieres, pásate por la tienda o llámanos y lo miramos contigo.';

return [{
  json: {
    ...entrada,
    pregunta: entrada.texto,
    datos_texto: JSON.stringify(saldo.apartados ?? []),
    respuesta_segura,
    cifras,
    saldo,
  },
}];

// Comprueba que la respuesta redactada lleva las cifras que han salido de la API.
// Si el modelo ha cambiado o inventado algun importe, se usa la respuesta segura.
//
// Asi el modelo redacta el tono, pero las cifras son siempre las de la tienda.
//
// Ojo: el item que llega aqui es el del modelo (solo trae su texto), asi que las
// cifras, la respuesta segura y el chat se recuperan del nodo que los preparo.
const entrada = $input.first().json ?? {};
const preparacion = $('Preparar respuesta del cliente').first().json ?? {};

const segura = String(preparacion.respuesta_segura ?? entrada.respuesta_segura ?? '');
const cifras = preparacion.cifras ?? entrada.cifras ?? [];

const redactado = String(entrada.output ?? entrada.text ?? '').trim();
const normalizar = (t) => String(t).replace(/\s/g, '').replace(',', '.');
const enElTexto = normalizar(redactado);

const faltan = cifras.filter((c) => !enElTexto.includes(normalizar(c)));

// Si el telefono no esta en la app no hay cifras que comprobar, y el modelo se inventaba
// un "error al consultar tu cuenta": en ese caso va siempre la respuesta del flujo.
const encontrado = preparacion.saldo?.encontrado !== false;
const aceptada = Boolean(redactado) && faltan.length === 0 && encontrado;
const respuesta = aceptada ? redactado : segura;

return [{
  json: {
    ...preparacion,
    ...entrada,
    respuesta,
    redaccion: aceptada ? 'aceptada' : 'sustituida',
    cifras_faltantes: faltan,
    chat_id: preparacion.chat_id ?? entrada.chat_id ?? '',
  },
}];

// Si el cliente todavia no ha dado su telefono, se le pide.
const entrada = $input.first().json ?? {};
const nombre = entrada.nombre ? entrada.nombre : '';
const cuerpo = [
  'Hola' + (nombre ? ' ' + nombre : '') + ',',
  '',
  'Para mirarte lo que te falta por pagar necesito el teléfono con el que hiciste el apartado',
  '(son 9 dígitos).',
  '',
  'En cuanto me lo pases te digo la cantidad y la fecha límite.',
].join('\n');

return [{ json: { ...entrada, respuesta: cuerpo, pide_telefono: true } }];
